import pytest
from pathlib import Path
from bs4 import BeautifulSoup

@pytest.fixture
def html_content():
    path = Path(__file__).parent / 'index.html'
    return path.read_text(encoding='utf-8')


def test_form_and_required_fields_exist(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    form = soup.find('form', {'id': 'claim-form'})
    assert form is not None, "Form with id 'claim-form' should exist"
    assert form.find('input', {'id': 'policy-number', 'aria-required': 'true'}) is not None, \
        "Input with id 'policy-number' should exist and be required"
    assert form.find('input', {'id': 'member-id', 'aria-required': 'true'}) is not None, \
        "Input with id 'member-id' should exist and be required"
    assert form.find('input', {'id': 'last-day-worked', 'aria-required': 'true'}) is not None, \
        "Input with id 'last-day-worked' should exist and be required"
    assert form.find('input', {'id': 'first-day-absent', 'aria-required': 'true'}) is not None, \
        "Input with id 'first-day-absent' should exist and be required"


def test_upload_input_allows_multiple_files(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    file_input = soup.find('input', {'type': 'file', 'id': 'documents'})
    assert file_input is not None, "File input with id 'documents' should exist"
    assert 'multiple' in file_input.attrs, "File input should allow multiple file uploads"


def test_confirmation_panel_and_status_markup_exist(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    confirmation = soup.find('div', {'id': 'confirmation', 'role': 'alert'})
    assert confirmation is not None, "Confirmation panel with id 'confirmation' should exist"
    status = confirmation.find('p', {'class': 'status'})
    assert status is not None and 'Status: Received' in status.text, "Status paragraph should indicate 'Status: Received'"


def test_member_lookup_mock_data_exists(html_content):
    # Check the script content for member mock data
    assert "const members = {'12345': 'John Doe', '67890': 'Jane Smith'};" in html_content, "Member lookup mock data should exist"


def test_reference_number_generation_code_exists(html_content):
    # Check the script content for reference number generation
    assert "function generateReference" in html_content, "The function 'generateReference' should exist for generating reference numbers"


def test_color_contrast_ratio(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    text_color = '#555555'
    background_color = '#ffffff'
    contrast_ratio = calculate_contrast_ratio(text_color, background_color)
    assert contrast_ratio >= 4.5, "Color contrast ratio should be at least 4.5:1"


def calculate_contrast_ratio(color1, color2):
    def hex_to_rgb(value):
        value = value.lstrip('#')
        return tuple(int(value[i:i+2], 16) for i in (0, 2, 4))

    def luminance(r, g, b):
        a = [v / 255.0 for v in (r, g, b)]
        a = [(v / 12.92) if (v <= 0.03928) else ((v + 0.055) / 1.055) ** 2.4 for v in a]
        return a[0] * 0.2126 + a[1] * 0.7152 + a[2] * 0.0722

    rgb1 = hex_to_rgb(color1)
    rgb2 = hex_to_rgb(color2)

    l1 = luminance(*rgb1)
    l2 = luminance(*rgb2)

    if l1 > l2:
        return (l1 + 0.05) / (l2 + 0.05)
    else:
        return (l2 + 0.05) / (l1 + 0.05)


